spec.expr:
min(
  kube_node_status_condition{
    condition="Ready",
    status="true",
    node=~"$node"
  }
)

sum(
  clamp_min(
    kube_deployment_spec_replicas{
      namespace=~"$namespace"
    }
    -
    kube_deployment_status_replicas_available{
      namespace=~"$namespace"
    },
    0
  )
)
or vector(0)

100 *
(
  kube_deployment_status_replicas_available{
    namespace=~"$namespace"
  }
/
  clamp_min(
    kube_deployment_spec_replicas{
      namespace=~"$namespace"
    },
    1
  )
)

100 *
(
  kube_statefulset_status_replicas_ready{
    namespace=~"$namespace"
  }
/
  clamp_min(
    kube_statefulset_replicas{
      namespace=~"$namespace"
    },
    1
  )
)

sum(
  kube_pod_status_phase{
    namespace="awx-operator",
    phase="Running"
  }
)
or vector(0)

sum(
  kube_pod_status_ready{
    namespace="awx-operator",
    condition="false"
  }
)
or vector(0)

sum(
  increase(
    kube_pod_container_status_restarts_total{
      namespace="awx-operator"
    }[$__range]
  )
)
or vector(0)

100 *
(
  kube_deployment_status_replicas_available{
    namespace="awx-operator"
  }
/
  clamp_min(
    kube_deployment_spec_replicas{
      namespace="awx-operator"
    },
    1
  )
)

100 *
(
  kube_statefulset_status_replicas_ready{
    namespace="awx-operator"
  }
/
  clamp_min(
    kube_statefulset_replicas{
      namespace="awx-operator"
    },
    1
  )
)

sum(
  kube_persistentvolumeclaim_status_phase{
    phase="Bound",
    namespace=~"$namespace"
  }
)
or vector(0)

sum(
  kube_persistentvolumeclaim_status_phase{
    phase=~"Pending|Lost",
    namespace=~"$namespace"
  }
)
or vector(0)

sum(
  kube_pod_status_phase{
    namespace=~"$namespace",
    phase="Running"
  }
)
or vector (0)

sum by (namespace, persistentvolumeclaim) (
  kube_persistentvolumeclaim_resource_requests_storage_bytes{
    namespace=~"$namespace"
  }
)

sum(
  kube_job_status_failed{
    namespace=~"$namespace"
  }
)
or vector(0)

sum by (namespace) (
  kube_job_status_succeeded{
    namespace=~"$namespace"
  }
)

sum by (namespace) (
  kube_job_status_active{
    namespace=~"$namespace"
  }
)

sum by (namespace) (
  kube_job_status_failed{
    namespace=~"$namespace"
  }
)

sum by (namespace, pod) (
  rate(
    container_cpu_usage_seconds_total{
      namespace=~"$namespace",
      pod!="",
      container!="",
      image!=""
    }[$__rate_interval]
  )
)

sum by (namespace, pod) (
  container_memory_working_set_bytes{
    namespace=~"$namespace",
    pod!="",
    container!="",
    image!=""
  }
)

topk(
  10,
  sum by (namespace, pod) (
    rate(
      container_cpu_usage_seconds_total{
        namespace=~"$namespace",
        pod!="",
        container!="",
        image!=""
      }[$__rate_interval]
    )
  )
)

topk(
  10,
  sum by (namespace, pod) (
    container_memory_working_set_bytes{
      namespace=~"$namespace",
      pod!="",
      container!="",
      image!=""
    }
  )
)

sum by (namespace) (
  rate(
    container_cpu_usage_seconds_total{
      namespace=~"$namespace",
      pod!="",
      container!="",
      image!=""
    }[$__rate_interval]
  )
)

sum by (namespace) (
  container_memory_working_set_bytes{
    namespace=~"$namespace",
    pod!="",
    container!="",
    image!=""
  }
)

sum by (namespace) (
  kube_pod_container_resource_requests{
    namespace=~"$namespace",
    resource="cpu",
    unit="core"
  }
)

sum(
  kube_pod_status_phase{
    namespace=~"$namespace",
    phase="Pending"
  }
)
or vector(0)

sum by (namespace) (
  kube_pod_container_resource_requests{
    namespace=~"$namespace",
    resource="memory",
    unit="byte"
  }
)

sum(
  kube_pod_status_unschedulable{
    namespace=~"$namespace"
  }
)
or vector(0)

sum(
  kube_pod_container_status_waiting{
    namespace=~"$namespace"
  }
)
or vector(0)

sum by (namespace, pod, reason) (
  kube_pod_container_status_waiting_reason{
    namespace=~"$namespace"
  }
)

100 *
sum by (namespace, pod) (
  rate(
    container_cpu_cfs_throttled_periods_total{
      namespace=~"$namespace",
      pod!="",
      container!="",
      image!=""
    }[$__rate_interval]
  )
)
/
clamp_min(
  sum by (namespace, pod) (
    rate(
      container_cpu_cfs_periods_total{
        namespace=~"$namespace",
        pod!="",
        container!="",
        image!=""
      }[$__rate_interval]
    )
  ),
  0.000001
)

sum(
  kube_pod_status_phase{
    namespace=~"$namespace",
    phase="Failed"
  } == 1
)
or vector(0)

sum by (phase) (
  kube_pod_status_phase{
    namespace=~"$namespace",
    phase=~"Pending|Running|Succeeded|Failed|Unknown"
  }
)

sum(
  kube_pod_status_ready{
    namespace=~"$namespace",
    condition="false"
  }
)
or vector(0)

sum(
  increase(
    kube_pod_container_status_restarts_total{
      namespace=~"$namespace"
    }[$__range]
  )
)
or vector(0)

count by (namespace) (
  kube_pod_info{
    namespace=~"$namespace"
  }
)

sum(
  (
    kube_deployment_status_replicas_available{
      namespace=~"$namespace"
    }
    ==
    kube_deployment_spec_replicas{
      namespace=~"$namespace"
    }
  )
)
or vector(0)
